import React from 'react';
import './AQIInputForm.css';

const AQIInputForm = ({ features, setFeatures, setResult }) => {
  const handleChange = (e) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch('http://localhost:5000/predict', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(features),
    });
    const data = await res.json();
    setResult(data);
  };

  return (
    <table className="aqi-input-table">
  <tbody>
    {[
      ['PM2.5', 'PM2_5', 'µg/m³'],
      ['CO', 'CO', 'ppb'],
      ['NO2', 'NO2', 'ppb'],
      ['NH3', 'NH3', 'ppb'],
      ['O3', 'O3', 'ppb'],
      ['Temp (°C)', 'Temp', '°C'],
      ['Humidity (%)', 'Humidity', '%'],
      ['Pressure (hPa)', 'Pressure', 'hPa'],
    ].map(([label, name, unit]) => (
      <tr key={name}>
        <td className="label-cell">{label}</td>
        <td>
          <input
            type="number"
            name={name}
            value={features[name]}
            onChange={handleChange}
            step="0.1"
            required
            className="input-cell"
          />
        </td>
        <td className="unit-cell">{unit}</td>
      </tr>
    ))}
    <button type="submit">Predict</button>
  </tbody>
</table>



  );
};

export default AQIInputForm;
